MODULE_PAIRS = (('test_project_description_main_integration', 'test_project_description_main_task_v2', 3), ('test_project_description_current_consumers', 'test_project_description_current_consumers_task_v2', 8), ('test_project_description_admission', 'test_project_description_admission_task_v2', 8), ('test_project_description_source_inverse', 'test_project_description_source_inverse_task_v2', 20))
SCHEMA='Description-Task-explicit39-route-v3'
def need(value,label):
 if value is not True:raise ValueError('Description39_route_refused:'+label)
def digest(value):return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def route_metadata():
 return {'schema':SCHEMA,'count':39,'mapping':[{'old':a,'new':b}for a,b in ROUTES],'mapping_sha256':digest(ROUTES)}
def _rows(rows):
 need(type(rows)is list and len(rows)>0,'nonempty_inventory')
 for row in rows:
  need(type(row)is dict and set(row)=={'id','module'}and type(row['id'])is str and type(row['module'])is str and row['id'].startswith(row['module']+'.'),'row_shape')
 ids=[r['id']for r in rows];need(len(ids)==len(set(ids)),'duplicate_id');return ids
def _closed_inventory(rows,routed):
 ids=_rows(rows);by_module={}
 for row in rows:by_module.setdefault(row['module'],[]).append(row['id'])
 old_ids={a for a,b in ROUTES};new_ids={b for a,b in ROUTES}
 need(len(ROUTES)==39 and len(old_ids)==39 and len(new_ids)==39 and not old_ids&new_ids,'closed_bijection')
 for old,new,count in MODULE_PAIRS:
  expected_old={a for a,b in ROUTES if a.startswith(old+'.')};expected_new={b for a,b in ROUTES if b.startswith(new+'.')}
  need(len(expected_old)==count==len(expected_new),'pair_count')
  need(set(by_module.get(new,[]))==expected_new,'exact_new_module')
  if routed:need(old not in by_module,'old_route_not_removed')
  else:need(set(by_module.get(old,[]))==expected_old,'exact_old_module')
 return old_ids,new_ids

def route_groups(groups,full):
 """Return original untouched module suites, minus exactly four old modules.
 Caller performs discovery/import/load_tests validation and executes these suites.
 """
 need(type(groups)is list,'group_shape');seen=set();flattened=[]
 for group in groups:
  need(type(group)is tuple and len(group)==3,'group_row');module,suite,rows=group
  need(type(module)is str and module not in seen and type(rows)is list and bool(rows),'module_group');seen.add(module)
  need(all(row['module']==module for row in rows),'whole_module');flattened.extend(rows)
 need(flattened==full,'exact_discovery_order')
 old_ids,_=_closed_inventory(full,False)
 old_modules={old for old,new,count in MODULE_PAIRS}
 routed=[group for group in groups if group[0]not in old_modules]
 selected=[row for module,suite,rows in routed for row in rows]
 need(selected==[row for row in full if row['id']not in old_ids],'only_exact39_removed')
 _closed_inventory(selected,True)
 return routed,selected,route_metadata()
def route_test_cases(tests):
 need(type(tests)is list and bool(tests),'case_shape')
 full=[{'id':t.id(),'module':t.__class__.__module__}for t in tests]
 old_ids,_=_closed_inventory(full,False)
 selected=[t for t in tests if t.id()not in old_ids]
 _closed_inventory([{'id':t.id(),'module':t.__class__.__module__}for t in selected],True)
 return selected

def validate_routed_inventory(full,metadata):
 need(type(metadata)is dict and metadata==route_metadata(),'exact_routing_metadata')
 _closed_inventory(full,True);return True
